use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn analyze_node_usage (symbol : & str , node : & serde_json :: Value , reports : & mut HashMap < i32 , NodeUsageReport >) { let integers = extract_integers_from_symbol (symbol) ; let user_type = classify_node_type (symbol) ; let relation_type = determine_relation_type (symbol) ; let ast_context = extract_ast_context (symbol) ; let crate_name = extract_crate_name (symbol) ; let level = node . get ("level") . and_then (| v | v . as_u64 ()) . unwrap_or (0) as usize ; let weight = node . get ("weight") . and_then (| v | v . as_f64 ()) . unwrap_or (0.0) ; let layer = node . get ("layer") . and_then (| v | v . as_str ()) . unwrap_or ("unknown") ; for integer in integers { let report = reports . entry (integer) . or_insert_with (| | NodeUsageReport { integer_value : integer , total_usage_count : 0 , user_types : HashMap :: new () , relations : HashMap :: new () , ast_contexts : HashMap :: new () , crate_distribution : HashMap :: new () , }) ; report . total_usage_count += 1 ; * report . user_types . entry (user_type . clone ()) . or_insert (0) += 1 ; * report . relations . entry (relation_type . clone ()) . or_insert (0) += 1 ; * report . ast_contexts . entry (ast_context . clone ()) . or_insert (0) += 1 ; * report . crate_distribution . entry (crate_name . clone ()) . or_insert (0) += 1 ; * report . ast_contexts . entry (format ! ("layer_{}" , layer)) . or_insert (0) += 1 ; * report . ast_contexts . entry (format ! ("level_{}" , level)) . or_insert (0) += 1 ; } }
}